/* ================= STYLE (plain CSS, not Tailwind — brand tokens) ================= */
const CSS = `
:root{
  --forest:#132F22; --forest-2:#1B4130; --green:#1F5C3E; --green-2:#3F8F5F;
  --gold:#B9891A; --gold-light:#F3E3BC; --paper:#FFE3C2; --panel:#FFFFFF;
  --ink:#1A1F1B; --ink-soft:#525B54; --line:#F3C89A; --line-soft:#F8DFC0;
  --red:#B3261E; --red-bg:#FBEAE9; --amber:#9A6A00; --amber-bg:#FBF1D6;
  --green-bg:#E7F3EA; --blue:#2255A4; --blue-bg:#E8EEF9; --radius:14px;
}
.annsetu-root{font-family:'Inter',sans-serif;background:#F5CE93;color:var(--ink);font-size:14px;line-height:1.5;min-height:100vh;}
.annsetu-root *{box-sizing:border-box;}
.annsetu-root h1,.annsetu-root h2,.annsetu-root h3,.annsetu-root h4{font-family:'Source Serif 4',serif;font-weight:600;margin:0;color:var(--forest);}
.annsetu-root .mono{font-family:'IBM Plex Mono',monospace;}
.annsetu-root button{font-family:inherit;font-size:13px;cursor:pointer;}

#login-screen{min-height:100vh;display:flex;align-items:center;justify-content:center;
  background:linear-gradient(180deg, rgba(19,47,34,0.94), rgba(19,47,34,0.94)),
  repeating-linear-gradient(135deg, rgba(255,255,255,0.02) 0 2px, transparent 2px 22px);}
.login-card{width:400px;background:var(--panel);border-radius:var(--radius);border:1px solid var(--line);padding:36px 34px 28px;box-shadow:0 30px 60px -20px rgba(0,0,0,0.45);}
.login-mark{display:flex;align-items:center;gap:10px;margin-bottom:22px;}
.seal{width:42px;height:42px;border-radius:50%;background:conic-gradient(from 210deg, var(--green) 0deg 300deg, var(--gold) 300deg 360deg);display:flex;align-items:center;justify-content:center;flex:none;}
.seal svg{width:22px;height:22px;}
.login-mark .titles h1{font-size:17px;line-height:1.15;text-transform:uppercase;letter-spacing:.03em;}
.login-mark .titles h1 .brand-ann{color:var(--forest);}
.login-mark .titles h1 .brand-disha{color:var(--gold);}
.login-mark .titles span{font-size:11px;color:var(--ink-soft);letter-spacing:.02em;}
.login-sub{font-size:12px;color:var(--ink-soft);border-top:1px solid var(--line-soft);padding-top:14px;margin-top:2px;margin-bottom:20px;}
.field{margin-bottom:14px;}
.field label{display:block;font-size:12px;color:var(--ink-soft);margin-bottom:5px;}
.field input{width:100%;padding:9px 11px;border:1px solid var(--line);border-radius:var(--radius);font-size:14px;background:#FCFDFB;}
.field input:focus{outline:2px solid var(--green-2);outline-offset:1px;border-color:var(--green-2);}
.btn{border:none;border-radius:var(--radius);padding:10px 16px;font-weight:600;transition:background .12s ease;}
.btn-primary{background:var(--forest);color:#fff;}
.btn-primary:hover{background:var(--forest-2);}
.btn-primary:disabled{opacity:.45;cursor:not-allowed;}
.btn-gold{background:var(--gold);color:#3A2A00;}
.btn-gold:hover{background:#A57A15;}
.btn-outline{background:transparent;border:1px solid var(--line);color:var(--ink);}
.btn-outline:hover{background:var(--line-soft);}
.btn-danger{background:var(--red);color:#fff;}
.btn-danger:hover{background:#94201A;}
.btn-sm{padding:6px 11px;font-size:12px;}
.btn-block{width:100%;}
.login-demo-note{margin-top:16px;font-size:11px;color:var(--ink-soft);background:var(--paper);border:1px dashed var(--line);padding:8px 10px;border-radius:var(--radius);}

#shell{display:flex;min-height:100vh;}
.sidebar{width:230px;background:#4E7A32;color:#F0F5E9;flex:none;min-height:100vh;display:flex;flex-direction:column;position:sticky;top:0;align-self:flex-start;height:100vh;border-right:1px solid #436B2A;}
.sidebar-brand{display:flex;align-items:center;gap:14px;padding:22px 18px 20px;background:var(--forest);border-bottom:1px solid rgba(0,0,0,0.25);}
.sidebar-brand .seal{width:96px;height:96px;}
.sidebar-brand .seal svg{width:50px;height:50px;}
.sidebar-brand div h1{font-size:48px;text-transform:uppercase;letter-spacing:.03em;}
.sidebar-brand div h1 .brand-ann{color:#F0F5E9;}
.sidebar-brand div h1 .brand-disha{color:var(--gold);}
.sidebar-brand div span{font-size:17px;color:#B9D2AA;}
.nav{list-style:none;margin:0;padding:10px 10px;overflow-y:auto;flex:1;}
.nav li{margin-bottom:2px;}
.nav button{width:100%;text-align:left;background:transparent;border:none;color:#DCEBD1;padding:9px 12px;border-radius:var(--radius);font-size:13px;display:flex;align-items:center;gap:10px;}
.nav button:hover{background:rgba(255,255,255,0.10);color:#fff;}
.nav button.active{background:var(--gold);color:#2C2000;font-weight:600;}
.nav .icon{width:15px;flex:none;opacity:.9;text-align:center;}
.sidebar-foot{padding:12px 18px;font-size:10.5px;color:#B9D2AA;border-top:1px solid rgba(255,255,255,0.15);}

.main{flex:1;min-width:0;display:flex;flex-direction:column;}
.topbar{height:56px;flex:none;background:#E8791A;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 22px;}
.topbar .crumb{font-size:13px;color:var(--ink-soft);}
.topbar .crumb strong{color:var(--ink);font-weight:600;}
.topbar .who{display:flex;align-items:center;gap:14px;font-size:12.5px;color:var(--ink-soft);}
.who .badge-id{background:#FFFFFF;border:1px solid var(--line);padding:3px 8px;border-radius:var(--radius);font-family:'IBM Plex Mono',monospace;font-size:11px;}
.logout-link{background:none;border:none;color:var(--green);font-weight:600;font-size:12.5px;}

.content{padding:24px 26px 60px;max-width:1280px;width:100%;margin:0 auto;}
.page-head{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:18px;flex-wrap:wrap;gap:10px;}
.page-head h2{font-size:21px;}
.page-head .sub{font-size:12.5px;color:var(--ink-soft);margin-top:4px;}

.panel{background:var(--panel);border:1px solid var(--line);border-radius:var(--radius);padding:18px 20px;margin-bottom:18px;box-shadow:0 2px 10px rgba(19,47,34,0.06);}
.panel-title{font-size:13px;font-weight:600;color:var(--forest);margin-bottom:14px;display:flex;align-items:center;justify-content:space-between;}
.panel-title .tag{font-size:10.5px;font-weight:600;color:var(--amber);background:var(--amber-bg);padding:2px 7px;border-radius:20px;}

.stat-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:18px;}
.stat-card{background:var(--panel);border:1px solid var(--line);border-radius:var(--radius);padding:16px 16px;border-top:3px solid var(--green);box-shadow:0 2px 10px rgba(19,47,34,0.06);}
.stat-card.gold{border-top-color:var(--gold);}
.stat-card.red{border-top-color:var(--red);}
.stat-card .num{font-family:'Source Serif 4',serif;font-size:26px;font-weight:600;color:var(--forest);}
.stat-card .lbl{font-size:12px;color:var(--ink-soft);margin-top:3px;}

.capacity-strip{display:grid;grid-template-columns:1fr 1fr 1fr;gap:14px;}
.cap-box{background:var(--panel);border:1px solid var(--line);border-radius:var(--radius);padding:16px;box-shadow:0 2px 10px rgba(19,47,34,0.06);}
.cap-box .lbl{font-size:12px;color:var(--ink-soft);margin-bottom:6px;}
.cap-box .num{font-family:'IBM Plex Mono',monospace;font-size:19px;font-weight:600;}
.bar-track{height:9px;background:var(--line-soft);border-radius:20px;overflow:hidden;margin-top:10px;}
.bar-fill{height:100%;border-radius:20px;}
.bar-fill.green{background:var(--green-2);}
.bar-fill.amber{background:var(--gold);}
.bar-fill.red{background:var(--red);}

table{width:100%;border-collapse:collapse;font-size:13px;}
thead th{text-align:left;font-size:11px;color:var(--ink-soft);font-weight:600;border-bottom:1px solid var(--line);padding:8px 10px;white-space:nowrap;}
tbody td{padding:10px 10px;border-bottom:1px solid var(--line-soft);vertical-align:middle;}
tbody tr:hover{background:var(--paper);}
tbody tr.clickable{cursor:pointer;}
.right{text-align:right;}

.badge{display:inline-block;font-size:11px;font-weight:600;padding:3px 9px;border-radius:20px;white-space:nowrap;}
.badge-pending{background:var(--amber-bg);color:var(--amber);}
.badge-verified{background:var(--green-bg);color:var(--green);}
.badge-rejected{background:var(--red-bg);color:var(--red);}
.badge-review{background:var(--blue-bg);color:var(--blue);}
.badge-allocated{background:var(--gold-light);color:#6B4E00;}
.badge-active{background:var(--green-bg);color:var(--green);}
.badge-closed{background:var(--line-soft);color:var(--ink-soft);}

.filters-row{display:flex;flex-wrap:wrap;gap:10px;margin-bottom:16px;align-items:center;}
.filters-row select,.filters-row input[type=text],.filters-row input[type=date]{padding:7px 10px;border:1px solid var(--line);border-radius:var(--radius);font-size:12.5px;background:#fff;}
.filters-row input[type=text]{min-width:220px;}
.filters-row .flex-spacer{flex:1;}

.stepper{display:flex;align-items:center;margin-bottom:6px;overflow-x:auto;}
.stepper .step{display:flex;align-items:center;flex:none;}
.stepper .dot{width:26px;height:26px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;border:2px solid var(--line);color:var(--ink-soft);background:#fff;flex:none;}
.stepper .dot.done{background:var(--green);border-color:var(--green);color:#fff;}
.stepper .dot.current{background:var(--gold);border-color:var(--gold);color:#3A2A00;}
.stepper .lbl{font-size:11px;color:var(--ink-soft);margin:0 8px 0 6px;white-space:nowrap;}
.stepper .lbl.done{color:var(--forest);font-weight:600;}
.stepper .connector{width:26px;height:2px;background:var(--line);flex:none;}
.stepper .connector.done{background:var(--green);}

.grid-2{display:grid;grid-template-columns:1fr 1fr;gap:18px;}
.kv{display:grid;grid-template-columns:1fr;gap:9px;}
.kv-row{display:flex;justify-content:space-between;gap:10px;font-size:13.5px;padding:6px 0;border-bottom:1px dashed var(--line-soft);}
.kv-row span:first-child{color:var(--ink-soft);}
.kv-row span:last-child{font-weight:600;}

.verify-check{display:flex;align-items:center;gap:8px;font-size:12.5px;color:var(--green);font-weight:600;margin-top:10px;}

.flow-box{background:var(--paper);border:1px solid var(--line);border-radius:var(--radius);padding:16px;text-align:center;font-size:12px;}
.flow-chain{display:flex;flex-direction:column;align-items:center;gap:2px;}
.flow-chain .flownode{background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:9px 20px;min-width:210px;}
.flow-chain .flownode .cap{font-size:10.5px;color:var(--ink-soft);}
.flow-chain .flownode .val{font-family:'IBM Plex Mono',monospace;font-weight:600;font-size:14px;color:var(--forest);}
.flow-chain .arrow{color:var(--ink-soft);font-size:14px;}
.flow-chain .flownode.result{border-color:var(--gold);background:var(--gold-light);}

.mock-terminal{background:#0F1B14;color:#B7E3C4;font-family:'IBM Plex Mono',monospace;font-size:12px;padding:14px 16px;border-radius:var(--radius);margin-top:10px;line-height:1.9;}
.mock-terminal .ok{color:#7FE0A0;float:right;}
.demo-tag{display:inline-block;font-size:10px;font-weight:700;letter-spacing:.03em;color:var(--amber);background:var(--amber-bg);padding:3px 8px;border-radius:20px;margin-top:8px;}

.recommend-card{border:1.5px solid var(--gold);border-radius:var(--radius);padding:18px 20px;background:linear-gradient(180deg,#FFFDF7,#fff);}
.recommend-card .star{color:var(--gold);font-size:12px;font-weight:700;letter-spacing:.02em;margin-bottom:8px;}
.recommend-card h3{font-size:17px;}
.recommend-card .code{font-family:'IBM Plex Mono',monospace;font-size:12px;color:var(--ink-soft);}
.reco-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:14px 0;}
.reco-stats .box{background:#fff;border:1px solid var(--line-soft);border-radius:var(--radius);padding:10px 12px;}
.reco-stats .box .l{font-size:10.5px;color:var(--ink-soft);}
.reco-stats .box .v{font-family:'IBM Plex Mono',monospace;font-weight:600;font-size:14px;}
.reason-box{background:var(--green-bg);border-radius:var(--radius);padding:10px 12px;font-size:12.5px;color:var(--green);margin-bottom:14px;}

.modal-bg{position:fixed;inset:0;background:rgba(19,29,22,0.5);z-index:50;align-items:center;justify-content:center;display:flex;}
.modal{background:#fff;border-radius:var(--radius);width:440px;max-width:92vw;padding:24px 26px;box-shadow:0 20px 60px rgba(0,0,0,0.3);max-height:86vh;overflow:auto;}
.modal h3{margin-bottom:14px;font-size:17px;}
.modal .kv-row{font-size:13px;}
.modal-actions{display:flex;gap:10px;margin-top:18px;}
.modal-actions .btn{flex:1;}

.toast-wrap{position:fixed;bottom:20px;right:20px;z-index:100;display:flex;flex-direction:column;gap:8px;}
.toast{background:var(--forest);color:#fff;padding:11px 18px;border-radius:var(--radius);font-size:13px;box-shadow:0 10px 26px rgba(0,0,0,0.25);border-left:4px solid var(--gold);min-width:230px;animation:slidein .18s ease;}
@keyframes slidein{from{opacity:0;transform:translateY(8px);}to{opacity:1;transform:translateY(0);}}

.token-card{border:1.5px dashed var(--gold);border-radius:var(--radius);padding:22px;text-align:center;background:var(--gold-light);}
.token-card .tlabel{font-size:11px;letter-spacing:.05em;color:#6B4E00;font-weight:700;}
.token-card .tnum{font-family:'IBM Plex Mono',monospace;font-size:24px;font-weight:700;color:var(--forest);margin:6px 0 14px;}

.timeline{display:flex;flex-direction:column;}
.tl-item{display:flex;gap:12px;padding:6px 0;}
.tl-dot{width:10px;height:10px;border-radius:50%;margin-top:4px;flex:none;background:var(--line);}
.tl-dot.done{background:var(--green);}
.tl-dot.next{background:var(--gold);}
.tl-line{width:1px;background:var(--line);flex:1;margin-left:4.5px;}
.tl-txt{font-size:13px;padding-bottom:14px;}
.tl-txt .t{font-weight:600;}
.tl-txt.done .t{color:var(--forest);}
.tl-txt.pending .t{color:var(--ink-soft);}

.footer-strip{text-align:center;font-size:11px;color:var(--ink-soft);padding:16px;border-top:1px solid var(--line);background:var(--panel);}
.empty-state{text-align:center;padding:40px 20px;color:var(--ink-soft);font-size:13px;}

.audit-item{display:flex;gap:14px;padding:12px 0;border-bottom:1px solid var(--line-soft);}
.audit-item .time{width:150px;flex:none;font-family:'IBM Plex Mono',monospace;font-size:11.5px;color:var(--ink-soft);}
.audit-item .body b{color:var(--forest);}

.form-row{margin-bottom:12px;}
.form-row label{display:block;font-size:12px;color:var(--ink-soft);margin-bottom:5px;}
.form-row input, .form-row select{width:100%;padding:8px 10px;border:1px solid var(--line);border-radius:var(--radius);font-size:13px;}
.two-col{display:grid;grid-template-columns:1fr 1fr;gap:12px;}
.link-btn{background:none;border:none;color:var(--green);font-weight:600;font-size:12.5px;padding:0;}

@media(max-width:980px){
  .stat-grid{grid-template-columns:repeat(2,1fr);}
  .capacity-strip{grid-template-columns:1fr;}
  .grid-2{grid-template-columns:1fr;}
  .reco-stats{grid-template-columns:repeat(2,1fr);}
  .sidebar{width:70px;}
  .sidebar-brand div, .nav .lbl-txt, .sidebar-foot{display:none;}
  .nav button{justify-content:center;}
}
`;

