function fmtNow() {
  return new Date().toLocaleString("en-IN", { day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit" });
}

function Seal({ small }) {
  const s = small ? 76 : 42;
  return (
    <div className="seal" style={{ width: s, height: s, background: "transparent" }}>
      <img src={LOGO_SRC} alt="AnnDisha logo" style={{ width: s, height: s, borderRadius: "50%", objectFit: "cover" }} />
    </div>
  );
}


function StatusBadge({ status }) {
  const map = {
    Pending: "badge-pending", Verified: "badge-verified", Rejected: "badge-rejected",
    "Manual Review": "badge-review", Allocated: "badge-allocated", "Slot Assigned": "badge-allocated",
    "Token Generated": "badge-allocated",
  };
  return <span className={`badge ${map[status] || "badge-pending"}`}>{status}</span>;
}

/* ================= MAIN APP ================= */
export default function AdminApp() {
  const [loggedIn, setLoggedIn] = useState(false);
  const [view, setView] = useState("dashboard");
  const [activeFarmerId, setActiveFarmerId] = useState(null);

  const [farmers, setFarmers] = useState(INITIAL_FARMERS);
  const [centres, setCentres] = useState(INITIAL_CENTRES);
  const [config, setConfig] = useState(INITIAL_CONFIG);
  const [auditLog, setAuditLog] = useState(INITIAL_AUDIT);

  const [filters, setFilters] = useState({ district: "", crop: "", verification: "", centre: "", search: "" });
  const [modal, setModal] = useState(null);
  const [toasts, setToasts] = useState([]);
  const [pendingAuto, setPendingAuto] = useState([]);
  const [slotDraftDate, setSlotDraftDate] = useState("2026-09-12");

  const allocCounterRef = useRef(452);
  const tokenCounterRef = useRef(452);

  const toast = (msg) => {
    const id = Math.random().toString(36).slice(2);
    setToasts((t) => [...t, { id, msg }]);
    setTimeout(() => setToasts((t) => t.filter((x) => x.id !== id)), 3200);
  };
  const logAudit = (action, detail) => {
    setAuditLog((log) => [{ time: fmtNow(), admin: "ADM-001", action, detail }, ...log]);
  };
  const closeModal = () => setModal(null);

  const findFarmer = (appId) => farmers.find((f) => f.appId === appId);
  const findCentre = (code) => centres.find((c) => c.code === code);
  const eligibleReady = (f) => f.idVerified && f.landVerified && f.cropVerified;

  const updateFarmer = (appId, patch) => {
    setFarmers((prev) => prev.map((f) => (f.appId === appId ? { ...f, ...(typeof patch === "function" ? patch(f) : patch) } : f)));
  };
  const updateCentre = (code, patch) => {
    setCentres((prev) => prev.map((c) => (c.code === code ? { ...c, ...(typeof patch === "function" ? patch(c) : patch) } : c)));
  };

  const go = (v, appId) => {
    setView(v);
    if (appId !== undefined) setActiveFarmerId(appId);
    if (typeof window !== "undefined") window.scrollTo(0, 0);
  };

  const openApp = (appId) => {
    const f = findFarmer(appId);
    if (f.status === "Verified") go("allocate", appId);
    else if (["Allocated", "Slot Assigned", "Token Generated"].includes(f.status)) go("slot", appId);
    else go("verify", appId);
  };

  /* ---------- verification actions ---------- */
  const verifyIdentity = (id) => {
    updateFarmer(id, { idVerified: true });
    const f = findFarmer(id);
    logAudit("Identity Verified", "Farmer: " + f.farmerId);
    toast("Identity verified for " + f.name);
  };
  const verifyLand = (id) => {
    updateFarmer(id, { landVerified: true });
    const f = findFarmer(id);
    logAudit("Land Record Verified", "Farmer: " + f.farmerId + " · Khata: " + f.khata);
    toast("Land record verified (demo)");
  };
  const verifyCrop = (id) => {
    updateFarmer(id, { cropVerified: true });
    const f = findFarmer(id);
    logAudit("Crop Details Verified", "Farmer: " + f.farmerId + " · Crop: " + f.crop);
    toast("Crop details verified");
  };
  const approveFarmer = (id) => {
    updateFarmer(id, { status: "Verified" });
    const f = findFarmer(id);
    logAudit("Farmer Verified", "Farmer: " + f.farmerId + " · Result: Approved");
    toast("Farmer verified successfully");
  };
  const manualReview = (id) => {
    updateFarmer(id, { status: "Manual Review" });
    const f = findFarmer(id);
    logAudit("Sent for Manual Review", "Farmer: " + f.farmerId);
    toast("Sent for manual review");
    go("applications");
  };
  const confirmReject = (id, reason) => {
    updateFarmer(id, { status: "Rejected", rejectionReason: reason });
    const f = findFarmer(id);
    logAudit("Farmer Rejected", "Farmer: " + f.farmerId + " · Reason: " + reason);
    closeModal();
    toast("Application rejected");
    go("applications");
  };

  /* ---------- centre scoring / allocation ---------- */
  const scoreCentres = (farmer) => {
    return centres
      .map((c) => {
        const dist = (DISTANCES[farmer.village] || {})[c.code] ?? 99;
        const available = c.capacity - c.allocated;
        const cropOk = c.crops.includes(farmer.crop);
        const activeOk = c.status === "ACTIVE";
        const openSlots = c.slots.filter((s) => s[2] < s[1]).length;
        const fits = available >= farmer.quantity;
        const eligible = cropOk && activeOk && fits && openSlots > 0;
        return { c, dist, available, cropOk, activeOk, openSlots, fits, eligible };
      })
      .sort((a, b) => a.dist - b.dist);
  };

  const confirmAllocation = (appId, code) => {
    const f = findFarmer(appId);
    const c = findCentre(code);
    allocCounterRef.current += 1;
    const allocId = "ALLOC-2026-" + String(allocCounterRef.current).padStart(5, "0");
    updateFarmer(appId, { centre: code, allocatedQty: f.quantity, allocationId: allocId, status: "Allocated", alreadyBooked: f.quantity });
    updateCentre(code, { allocated: c.allocated + f.quantity, farmers: c.farmers + 1 });
    logAudit("Centre Assigned", "Centre: " + code + " · Farmer: " + f.farmerId + " · Quantity: " + f.quantity.toFixed(2) + " Qtl");
    closeModal();
    toast("Centre assigned — Allocation ID " + allocId);
    go("slot", appId);
  };

  const autoAssignAll = () => {
    const rows = farmers.filter((f) => f.status === "Verified");
    if (!rows.length) { toast("No farmers awaiting allocation"); return; }
    const proposals = rows.map((f) => {
      const scored = scoreCentres(f);
      const best = scored.find((s) => s.eligible);
      return { f, best };
    });
    setPendingAuto(proposals);
    setModal({ type: "autoAssign" });
  };
  const confirmAutoAssign = () => {
    let count = 0;
    setFarmers((prevFarmers) => {
      let nextFarmers = prevFarmers;
      setCentres((prevCentres) => {
        let nextCentres = prevCentres;
        pendingAuto.forEach(({ f, best }) => {
          if (!best) return;
          allocCounterRef.current += 1;
          const allocId = "ALLOC-2026-" + String(allocCounterRef.current).padStart(5, "0");
          nextFarmers = nextFarmers.map((x) =>
            x.appId === f.appId ? { ...x, centre: best.c.code, allocatedQty: f.quantity, allocationId: allocId, status: "Allocated", alreadyBooked: f.quantity } : x
          );
          nextCentres = nextCentres.map((c) => (c.code === best.c.code ? { ...c, allocated: c.allocated + f.quantity, farmers: c.farmers + 1 } : c));
          logAudit("Centre Assigned (Auto)", "Centre: " + best.c.code + " · Farmer: " + f.farmerId + " · Quantity: " + f.quantity.toFixed(2) + " Qtl");
          count++;
        });
        return nextCentres;
      });
      return nextFarmers;
    });
    closeModal();
    toast(count + " farmer(s) auto-assigned to centres");
    go("unassigned");
  };

  /* ---------- slot / token ---------- */
  const selectSlot = (appId, time) => {
    const dateObj = new Date(slotDraftDate);
    const slotDateStr = isNaN(dateObj) ? "12 September 2026" : dateObj.toLocaleDateString("en-IN", { day: "2-digit", month: "long", year: "numeric" });
    updateFarmer(appId, { slot: time, slotDate: slotDateStr });
    toast("Slot " + time + " selected");
  };
  const generateToken = (appId) => {
    const f = findFarmer(appId);
    const c = findCentre(f.centre);
    tokenCounterRef.current += 1;
    updateCentre(c.code, { slots: c.slots.map((s) => (s[0] === f.slot ? [s[0], s[1], s[2] + 1] : s)) });
    const tokenNo = "UP-GON-2026-" + String(tokenCounterRef.current).padStart(5, "0");
    updateFarmer(appId, { tokenNo, status: "Token Generated" });
    logAudit("Token Generated", "Farmer: " + f.farmerId + " · Token: " + tokenNo + " · Centre: " + c.code);
    toast("Token generated: " + tokenNo);
  };

  /* ---------- centre management ---------- */
  const saveCapacity = (code, val) => {
    const c = findCentre(code);
    if (val < c.allocated) { toast("Capacity cannot be less than already-allocated quantity"); return; }
    updateCentre(code, { capacity: val });
    logAudit("Centre Capacity Updated", "Centre: " + code + " · New capacity: " + val + " Qtl");
    closeModal();
    toast("Capacity updated");
  };
  const saveSlot = (code, time, cap) => {
    const c = findCentre(code);
    updateCentre(code, { slots: [...c.slots, [time || "New Slot", cap || 10, 0]] });
    logAudit("Slot Added", "Centre: " + code + " · Slot: " + (time || "New Slot"));
    closeModal();
    toast("Slot added");
  };
  const toggleCentre = (code) => {
    const c = findCentre(code);
    const next = c.status === "ACTIVE" ? "CLOSED" : "ACTIVE";
    updateCentre(code, { status: next });
    logAudit(next === "ACTIVE" ? "Centre Reopened" : "Centre Closed", "Centre: " + code);
    toast("Centre " + (next === "ACTIVE" ? "reopened" : "closed"));
  };

  /* ---------- settings ---------- */
  const saveYields = (newRates) => {
    setConfig((cfg) => ({ ...cfg, yieldPerHectare: newRates }));
    setFarmers((prev) =>
      prev.map((f) => {
        if (["Pending", "Verified", "Manual Review"].includes(f.status) && newRates[f.crop]) {
          return { ...f, quantity: +(f.cropArea * newRates[f.crop]).toFixed(2) };
        }
        return f;
      })
    );
    logAudit("Eligibility Formula Updated", "Yield rates revised by ADM-001");
    toast("Formula saved — eligibility recalculated for pending farmers");
  };
  const toggleAutoSplit = (val) => {
    setConfig((cfg) => ({ ...cfg, autoSplitAllocation: val }));
    logAudit("Allocation Policy Updated", "Auto-split set to " + val);
    toast("Policy updated");
  };

  /* ---------- filters ---------- */
  const applyFilters = (list) => {
    const f = filters;
    return list.filter(
      (x) =>
        (!f.district || x.district === f.district) &&
        (!f.crop || x.crop === f.crop) &&
        (!f.verification || x.status === f.verification) &&
        (!f.centre || x.centre === f.centre) &&
        (!f.search ||
          x.name.toLowerCase().includes(f.search.toLowerCase()) ||
          x.appId.toLowerCase().includes(f.search.toLowerCase()) ||
          x.farmerId.toLowerCase().includes(f.search.toLowerCase()) ||
          x.mobile.includes(f.search))
    );
  };

  /* ================= RENDER: LOGIN ================= */
  if (!loggedIn) {
    return (
      <div className="annsetu-root">
        <style>{CSS}</style>
        <div id="login-screen">
          <div className="login-card">
            <div className="login-mark">
              <Seal />
              <div className="titles">
                <h1><span className="brand-ann">Ann</span><span className="brand-disha">Disha</span></h1>
                <span>CROP PROCUREMENT MANAGEMENT — ADMIN PORTAL</span>
              </div>
            </div>
            <div className="login-sub">
              Sign in with your administrator credentials to verify farmers, calculate eligibility and allocate procurement centres.
            </div>
            <div className="field"><label>Admin ID</label><input type="text" defaultValue="ADM-001" /></div>
            <div className="field"><label>Password</label><input type="password" defaultValue="••••••••" /></div>
            <div className="field"><label>OTP</label><input type="text" placeholder="6-digit OTP" maxLength={6} defaultValue="482913" /></div>
            <button className="btn btn-primary btn-block" onClick={() => setLoggedIn(true)}>Sign in to Admin Dashboard</button>
            <div className="login-demo-note">Demo credentials are pre-filled. This is a prototype login — no real authentication or government system is contacted.</div>
          </div>
        </div>
      </div>
    );
  }

  const crumbFor = () => {
    const map = {
      dashboard: "Dashboard", applications: "Farmer Applications", "verification-list": "Farmer Verification",
      eligible: "Eligible Farmers", centres: "Procurement Centres",
      tokens: "Token Management", procurement: "Procurement", payments: "Payments",
      reports: "Reports", complaints: "Complaints", settings: "Settings",
    };
    if (view === "verify") return <>Farmer Verification &rsaquo; <strong>{activeFarmerId}</strong></>;
    if (view === "allocate") return <>Centre Allocation &rsaquo; <strong>{activeFarmerId}</strong></>;
    if (view === "slot") return <>Slot &amp; Token &rsaquo; <strong>{activeFarmerId}</strong></>;
    return map[view] || "AnnDisha";
  };

  /* ================= SHARED PIECES ================= */
  const FilterControls = () => {
    const districts = [...new Set(farmers.map((f) => f.district))];
    const crops = [...new Set(farmers.map((f) => f.crop))];
    const statuses = [...new Set(farmers.map((f) => f.status))];
    return (
      <div className="filters-row">
        <select value={filters.district} onChange={(e) => setFilters((f) => ({ ...f, district: e.target.value }))}>
          <option value="">All districts</option>
          {districts.map((d) => <option key={d} value={d}>{d}</option>)}
        </select>
        <select value={filters.crop} onChange={(e) => setFilters((f) => ({ ...f, crop: e.target.value }))}>
          <option value="">All crops</option>
          {crops.map((c) => <option key={c} value={c}>{c}</option>)}
        </select>
        <select value={filters.verification} onChange={(e) => setFilters((f) => ({ ...f, verification: e.target.value }))}>
          <option value="">All statuses</option>
          {statuses.map((s) => <option key={s} value={s}>{s}</option>)}
        </select>
        <select value={filters.centre} onChange={(e) => setFilters((f) => ({ ...f, centre: e.target.value }))}>
          <option value="">All centres</option>
          {centres.map((c) => <option key={c.code} value={c.code}>{c.name}</option>)}
        </select>
        <div className="flex-spacer" />
        <input type="text" placeholder="Search name, application ID, farmer ID or mobile" value={filters.search}
          onChange={(e) => setFilters((f) => ({ ...f, search: e.target.value }))} />
      </div>
    );
  };

  const WorkflowStepper = ({ farmer }) => {
    const steps = ["Verify", "Eligibility", "Allocate Centre", "Generate Token"];
    let currentIdx = 0;
    if (farmer.status === "Verified") currentIdx = 2;
    else if (farmer.status === "Allocated") currentIdx = 3;
    else if (farmer.status === "Slot Assigned") currentIdx = 3;
    else if (farmer.status === "Token Generated") currentIdx = 4;
    return (
      <div className="stepper">
        {steps.map((s, i) => {
          const done = i < currentIdx, current = i === currentIdx;
          return (
            <React.Fragment key={s}>
              {i > 0 && <div className={`connector ${i <= currentIdx - 1 || done ? "done" : ""}`} />}
              <div className="step">
                <div className={`dot ${done ? "done" : current ? "current" : ""}`}>{done ? "✓" : i + 1}</div>
                <div className={`lbl ${done ? "done" : ""}`}>{s}</div>
              </div>
            </React.Fragment>
          );
        })}
      </div>
    );
  };

  const StatusTimeline = ({ f }) => {
    const stages = [
      ["Application Submitted", true],
      ["Identity Verified", f.idVerified],
      ["Land Verified", f.landVerified],
      ["Crop Verified", f.cropVerified],
      ["Eligibility Approved", ["Verified", "Allocated", "Slot Assigned", "Token Generated"].includes(f.status)],
      ["Centre Assigned", ["Allocated", "Slot Assigned", "Token Generated"].includes(f.status)],
      ["Slot Assigned", !!f.slot],
      ["Token Generated", f.status === "Token Generated"],
      ["Farmer Arrived", false],
      ["Procurement Completed", false],
      ["Payment Completed", false],
    ];
    let nextSet = false;
    return (
      <div className="timeline">
        {stages.map(([label, done], i) => {
          const isNext = !done && !nextSet ? ((nextSet = true), true) : false;
          return (
            <div className="tl-item" key={label}>
              <div style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
                <div className={`tl-dot ${done ? "done" : isNext ? "next" : ""}`} />
                {i < stages.length - 1 && <div className="tl-line" />}
              </div>
              <div className={`tl-txt ${done ? "done" : "pending"}`}><div className="t">{label}</div></div>
            </div>
          );
        })}
      </div>
    );
  };

  /* ================= PAGE: DASHBOARD ================= */
  const Dashboard = () => {
    const registered = farmers.length + 12530;
    const pendingVer = farmers.filter((x) => x.status === "Pending").length + 180;
    const verified = farmers.filter((x) => ["Verified", "Allocated", "Slot Assigned", "Token Generated"].includes(x.status)).length + 11855;
    const rejected = farmers.filter((x) => x.status === "Rejected").length + 495;
    const activeCentres = centres.filter((c) => c.status === "ACTIVE").length + 24;
    const totalCap = centres.reduce((s, c) => s + c.capacity, 0) + 7400;
    const booked = centres.reduce((s, c) => s + c.allocated, 0) + 6000;
    const remaining = totalCap - booked;
    const pct = Math.round((booked / totalCap) * 100);
    const barClass = pct > 90 ? "red" : pct > 70 ? "amber" : "green";

    return (
      <>
        <div className="page-head">
          <div><h2>Dashboard</h2><div className="sub">Overview of registrations, verification and today's procurement capacity.</div></div>
        </div>
        <div className="stat-grid">
          <div className="stat-card"><div className="num">{registered.toLocaleString("en-IN")}</div><div className="lbl">Registered Farmers</div></div>
          <div className="stat-card gold"><div className="num">{pendingVer}</div><div className="lbl">Pending Verification</div></div>
          <div className="stat-card"><div className="num">{verified.toLocaleString("en-IN")}</div><div className="lbl">Verified Farmers</div></div>
          <div className="stat-card red"><div className="num">{rejected}</div><div className="lbl">Rejected Applications</div></div>
        </div>
        <div className="stat-grid">
          <div className="stat-card"><div className="num">{activeCentres}</div><div className="lbl">Active Procurement Centres</div></div>
          <div className="stat-card"><div className="num">{totalCap.toLocaleString("en-IN")} Qtl</div><div className="lbl">Today's Capacity</div></div>
          <div className="stat-card"><div className="num">{booked.toLocaleString("en-IN")} Qtl</div><div className="lbl">Today's Booked Capacity</div></div>
        </div>
        <div className="panel">
          <div className="panel-title">Today's Procurement Capacity</div>
          <div className="capacity-strip">
            <div className="cap-box"><div className="lbl">Total capacity</div><div className="num">{totalCap.toLocaleString("en-IN")} Qtl</div></div>
            <div className="cap-box">
              <div className="lbl">Booked</div><div className="num">{booked.toLocaleString("en-IN")} Qtl</div>
              <div className="bar-track"><div className={`bar-fill ${barClass}`} style={{ width: pct + "%" }} /></div>
            </div>
            <div className="cap-box"><div className="lbl">Remaining</div><div className="num" style={{ color: "var(--green)" }}>{remaining.toLocaleString("en-IN")} Qtl</div></div>
          </div>
        </div>
        <div className="grid-2">
          <div className="panel">
            <div className="panel-title">Farmers awaiting action<button className="link-btn" onClick={() => go("eligible")}>View all →</button></div>
            <table>
              <thead><tr><th>Farmer</th><th>Village</th><th>Crop</th><th>Status</th></tr></thead>
              <tbody>
                {farmers.filter((x) => x.status === "Pending" || x.status === "Verified").slice(0, 5).map((x) => (
                  <tr key={x.appId} className="clickable" onClick={() => go(x.status === "Pending" ? "verify" : "allocate", x.appId)}>
                    <td>{x.name}<div className="mono" style={{ fontSize: 10.5, color: "var(--ink-soft)" }}>{x.farmerId}</div></td>
                    <td>{x.village}</td><td>{x.crop}</td><td><StatusBadge status={x.status} /></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div className="panel">
            <div className="panel-title">Recent audit activity<button className="link-btn" onClick={() => go("reports")}>Full log →</button></div>
            {auditLog.slice(0, 5).map((a, i) => (
              <div className="audit-item" key={i}>
                <div className="time">{a.time}</div>
                <div className="body"><b>{a.action}</b><br /><span style={{ color: "var(--ink-soft)" }}>{a.detail}</span></div>
              </div>
            ))}
          </div>
        </div>
      </>
    );
  };

  /* ================= PAGE: APPLICATIONS ================= */
  const Applications = ({ title }) => {
    const rows = applyFilters(farmers);
    return (
      <>
        <div className="page-head">
          <div><h2>{title}</h2><div className="sub">{rows.length} of {farmers.length} applications shown</div></div>
        </div>
        <FilterControls />
        <div className="panel" style={{ padding: 0 }}>
          <table>
            <thead><tr><th>Application ID</th><th>Farmer</th><th>Village</th><th>Crop</th><th className="right">Quantity</th><th>Verification</th><th>Centre</th><th>Status</th></tr></thead>
            <tbody>
              {rows.length ? rows.map((f) => (
                <tr key={f.appId} className="clickable" onClick={() => openApp(f.appId)}>
                  <td className="mono">{f.appId}</td>
                  <td>{f.name}<div className="mono" style={{ fontSize: 10.5, color: "var(--ink-soft)" }}>{f.farmerId}</div></td>
                  <td>{f.village}</td>
                  <td>{f.crop}</td>
                  <td className="right mono">{eligibleReady(f) ? f.quantity.toFixed(2) + " Qtl" : <span style={{ color: "var(--ink-soft)", fontStyle: "italic" }}>Pending</span>}</td>
                  <td><StatusBadge status={f.status} /></td>
                  <td>{f.centre ? <span className="mono">{f.centre}</span> : "—"}</td>
                  <td><StatusBadge status={f.status} /></td>
                </tr>
              )) : <tr><td colSpan={8}><div className="empty-state">No applications match the current filters.</div></td></tr>}
            </tbody>
          </table>
        </div>
      </>
    );
  };

  /* ================= PAGE: ELIGIBLE ================= */
  const Eligible = () => {
    const rows = farmers.filter((f) => f.status === "Verified");
    return (
      <>
        <div className="page-head"><div><h2>Eligible Farmers</h2><div className="sub">Verified farmers with a calculated eligible quantity, awaiting centre allocation.</div></div></div>
        <div className="panel" style={{ padding: 0 }}>
          <table>
            <thead><tr><th>Farmer</th><th>Village</th><th>Crop</th><th className="right">Eligible Qty</th><th>Action</th></tr></thead>
            <tbody>
              {rows.length ? rows.map((f) => (
                <tr key={f.appId}>
                  <td>{f.name}<div className="mono" style={{ fontSize: 10.5, color: "var(--ink-soft)" }}>{f.farmerId}</div></td>
                  <td>{f.village}</td><td>{f.crop}</td><td className="right mono">{f.quantity.toFixed(2)} Qtl</td>
                  <td><button className="btn btn-gold btn-sm" onClick={() => go("allocate", f.appId)}>Allocate Centre</button></td>
                </tr>
              )) : <tr><td colSpan={5}><div className="empty-state">No verified farmers awaiting allocation right now.</div></td></tr>}
            </tbody>
          </table>
        </div>
      </>
    );
  };

  /* ================= PAGE: VERIFY ================= */
  const Verify = ({ appId }) => {
    const f = findFarmer(appId);
    if (!f) return <div className="empty-state">Farmer not found.</div>;
    const allDone = eligibleReady(f);
    const rate = config.yieldPerHectare[f.crop];
    const rejectReasons = ["Land record mismatch", "Duplicate farmer", "Invalid information", "Crop information mismatch", "Documents/data could not be verified"];

    return (
      <>
        <div className="page-head">
          <div><h2>Farmer Verification</h2><div className="sub">Application ID: <span className="mono">{f.appId}</span> &nbsp;·&nbsp; Status: <StatusBadge status={f.status} /></div></div>
          <button className="btn btn-outline btn-sm" onClick={() => go("applications")}>← Back to applications</button>
        </div>
        <div className="panel"><WorkflowStepper farmer={f} /></div>

        <div className="grid-2">
          <div className="panel">
            <div className="panel-title">A. Farmer Identity</div>
            <div className="kv">
              <div className="kv-row"><span>Farmer Name</span><span>{f.name}</span></div>
              <div className="kv-row"><span>Father's Name</span><span>{f.father}</span></div>
              <div className="kv-row"><span>Farmer ID</span><span className="mono">{f.farmerId}</span></div>
              <div className="kv-row"><span>Mobile</span><span className="mono">******{f.mobile.slice(-4)}</span></div>
              <div className="kv-row"><span>District</span><span>{f.district}</span></div>
              <div className="kv-row"><span>Tehsil</span><span>{f.tehsil}</span></div>
              <div className="kv-row"><span>Village</span><span>{f.village}</span></div>
            </div>
            {f.idVerified ? <div className="verify-check">✓ Identity Verified</div> :
              <button className="btn btn-primary" style={{ marginTop: 12 }} onClick={() => verifyIdentity(appId)}>Verify Identity</button>}
          </div>

          <div className="panel">
            <div className="panel-title">B. Land Record Verification</div>
            <div className="kv">
              <div className="kv-row"><span>Khata Number</span><span className="mono">{f.khata}</span></div>
              <div className="kv-row"><span>Khasra Number</span><span className="mono">{f.khasra}</span></div>
              <div className="kv-row"><span>Village</span><span>{f.village}</span></div>
              <div className="kv-row"><span>Recorded Area</span><span>{f.landArea.toFixed(2)} Hectares</span></div>
              <div className="kv-row"><span>Ownership</span><span>{f.ownership}</span></div>
            </div>
            {f.landVerified ? (
              <>
                <div className="mock-terminal">
                  Connecting to Government Verification Service...<br />
                  Farmer ID&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span className="ok">✓</span><br />
                  Village&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span className="ok">✓</span><br />
                  Khata Number&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span className="ok">✓</span><br />
                  Khasra Number&nbsp;&nbsp;&nbsp;&nbsp;<span className="ok">✓</span><br />
                  Land Area&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span className="ok">✓</span><br />
                  Ownership&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span className="ok">✓</span><br /><br />
                  <strong>Land Record Verified</strong>
                </div>
                <div className="demo-tag">DEMO / MOCK GOVERNMENT VERIFICATION</div>
              </>
            ) : (
              <>
                <button className="btn btn-primary" style={{ marginTop: 12 }} onClick={() => verifyLand(appId)}>Verify Land Record</button>
                <div className="demo-tag">DEMO / MOCK GOVERNMENT VERIFICATION</div>
              </>
            )}
          </div>
        </div>

        <div className="grid-2">
          <div className="panel">
            <div className="panel-title">C. Crop Verification</div>
            <div className="kv">
              <div className="kv-row"><span>Crop</span><span>{f.crop}</span></div>
              <div className="kv-row"><span>Season</span><span>{f.season}</span></div>
              <div className="kv-row"><span>Declared Crop Area</span><span>{f.cropArea.toFixed(2)} Hectares</span></div>
              <div className="kv-row"><span>Expected Production</span>
                <span>{f.cropVerified ? f.quantity.toFixed(2) + " Qtl" : <span style={{ color: "var(--ink-soft)", fontStyle: "italic" }}>Calculated after crop verification</span>}</span>
              </div>
            </div>
            {f.cropVerified ? <div className="verify-check">✓ Crop Details Verified</div> :
              <button className="btn btn-primary" style={{ marginTop: 12 }} onClick={() => verifyCrop(appId)}>Verify Crop Details</button>}
          </div>

          <div className="panel">
            <div className="panel-title">D. Eligibility Calculation <span className="tag">Formula from Settings</span></div>
            {!allDone ? (
              <>
                <div className="flow-box" style={{ opacity: 0.6 }}>
                  <div className="flow-chain">
                    <div className="flownode"><div className="cap">LAND AREA</div><div className="val">{f.idVerified && f.landVerified ? f.landArea.toFixed(2) + " Hectares" : "—"}</div></div>
                    <div className="arrow">↓</div>
                    <div className="flownode"><div className="cap">CROP AREA</div><div className="val">{f.cropVerified ? f.cropArea.toFixed(2) + " Hectares" : "—"}</div></div>
                    <div className="arrow">↓</div>
                    <div className="flownode result"><div className="cap">ELIGIBLE QUANTITY</div><div className="val">Not yet decided</div></div>
                  </div>
                </div>
                <div style={{ fontSize: 12, color: "var(--ink-soft)", marginTop: 12 }}>
                  Eligible quantity is decided only once identity, land record and crop details are all verified.{" "}
                  {[!f.idVerified && "Identity", !f.landVerified && "Land record", !f.cropVerified && "Crop details"].filter(Boolean).join(", ")} still pending.
                </div>
              </>
            ) : (
              <>
                <div className="flow-box">
                  <div className="flow-chain">
                    <div className="flownode"><div className="cap">LAND AREA</div><div className="val">{f.landArea.toFixed(2)} Hectares</div></div>
                    <div className="arrow">↓</div>
                    <div className="flownode"><div className="cap">CROP AREA</div><div className="val">{f.cropArea.toFixed(2)} Hectares</div></div>
                    <div className="arrow">↓</div>
                    <div className="flownode"><div className="cap">VERIFIED CROP</div><div className="val">{f.crop}</div></div>
                    <div className="arrow">↓</div>
                    <div className="flownode result"><div className="cap">ELIGIBLE QUANTITY</div><div className="val">{f.quantity.toFixed(2)} Quintals</div></div>
                  </div>
                </div>
                <div className="kv" style={{ marginTop: 14 }}>
                  <div className="kv-row"><span>Eligible Quantity</span><span>{f.quantity.toFixed(2)} Qtl</span></div>
                  <div className="kv-row"><span>Already Procured</span><span>{f.alreadyProcured.toFixed(2)} Qtl</span></div>
                  <div className="kv-row"><span>Already Booked</span><span>{f.alreadyBooked.toFixed(2)} Qtl</span></div>
                  <div className="kv-row"><span>Remaining Eligible Quantity</span><span>{(f.quantity - f.alreadyProcured - f.alreadyBooked).toFixed(2)} Qtl</span></div>
                </div>
                <div style={{ fontSize: 11, color: "var(--ink-soft)", marginTop: 10 }}>
                  Calculated as crop area × configured yield/hectare for {f.crop} ({rate || "—"} Qtl/ha). <button className="link-btn" onClick={() => go("settings")}>Edit formula</button>
                </div>
              </>
            )}
          </div>
        </div>

        <div className="panel">
          <div className="panel-title">Verification Result</div>
          {f.status === "Rejected" ? (
            <div style={{ color: "var(--red)", fontWeight: 600 }}>This application was rejected. Reason: {f.rejectionReason}</div>
          ) : ["Verified", "Allocated", "Slot Assigned", "Token Generated"].includes(f.status) ? (
            <>
              <div style={{ color: "var(--green)", fontWeight: 600 }}>✓ Farmer Verified Successfully — eligible for procurement-centre allocation.</div>
              <button className="btn btn-gold btn-sm" style={{ marginTop: 12 }} onClick={() => go("allocate", appId)}>Continue to Centre Allocation →</button>
            </>
          ) : (
            <>
              <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
                <button className="btn btn-primary" disabled={!allDone} onClick={() => approveFarmer(appId)}>Approve</button>
                <button className="btn btn-outline" onClick={() => manualReview(appId)}>Send for Manual Review</button>
                <button className="btn btn-danger" onClick={() => setModal({ type: "reject", appId, reason: rejectReasons[0] })}>Reject</button>
              </div>
              {!allDone && <div style={{ fontSize: 11.5, color: "var(--ink-soft)", marginTop: 10 }}>Complete identity, land and crop verification before approving.</div>}
            </>
          )}
        </div>
      </>
    );
  };

  /* ================= PAGE: ALLOCATE ================= */
  const Allocate = ({ appId }) => {
    const f = findFarmer(appId);
    if (!f) return <div className="empty-state">Farmer not found.</div>;
    if (["Pending", "Rejected", "Manual Review"].includes(f.status)) {
      return (
        <div className="empty-state">
          This farmer must be verified before centre allocation.<br />
          <button className="btn btn-primary" style={{ marginTop: 14 }} onClick={() => go("verify", appId)}>Go to Verification</button>
        </div>
      );
    }
    if (["Allocated", "Slot Assigned", "Token Generated"].includes(f.status)) {
      const c = findCentre(f.centre);
      return (
        <>
          <div className="page-head"><div><h2>Centre Allocation</h2><div className="sub">This farmer already has an assigned centre.</div></div></div>
          <div className="panel">
            <div className="panel-title">Already Assigned</div>
            <div className="kv-row"><span>Centre</span><span>{c.name}</span></div>
            <div className="kv-row"><span>Allocation ID</span><span className="mono">{f.allocationId}</span></div>
            <div className="kv-row"><span>Allocated Quantity</span><span>{f.allocatedQty.toFixed(2)} Qtl</span></div>
            <button className="btn btn-gold btn-sm" style={{ marginTop: 14 }} onClick={() => go("slot", appId)}>Continue to Slot &amp; Token →</button>
          </div>
        </>
      );
    }

    const scored = scoreCentres(f);
    const recommended = scored.find((s) => s.eligible) || null;
    const alternatives = scored.filter((s) => (recommended ? s.c.code !== recommended.c.code : true)).slice(0, 4);

    return (
      <>
        <div className="page-head">
          <div><h2>Centre Allocation</h2><div className="sub">Application ID: <span className="mono">{f.appId}</span></div></div>
          <button className="btn btn-outline btn-sm" onClick={() => go("applications")}>← Back to applications</button>
        </div>
        <div className="panel"><WorkflowStepper farmer={f} /></div>

        <div className="panel">
          <div className="panel-title">Farmer</div>
          <div className="grid-2">
            <div className="kv"><div className="kv-row"><span>Farmer</span><span>{f.name}</span></div><div className="kv-row"><span>Village</span><span>{f.village}</span></div></div>
            <div className="kv"><div className="kv-row"><span>District</span><span>{f.district}</span></div><div className="kv-row"><span>Crop</span><span>{f.crop}</span></div></div>
          </div>
          <div className="kv-row" style={{ marginTop: 6 }}><span>Eligible Quantity</span><span>{f.quantity.toFixed(2)} Qtl</span></div>
        </div>

        {recommended ? (
          <div className="recommend-card">
            <div className="star">⭐ RECOMMENDED CENTRE</div>
            <h3>{recommended.c.name}</h3>
            <div className="code">Centre Code: {recommended.c.code}</div>
            <div className="reco-stats">
              <div className="box"><div className="l">Distance</div><div className="v">{recommended.dist.toFixed(1)} km</div></div>
              <div className="box"><div className="l">Today's Capacity</div><div className="v">{recommended.c.capacity} Qtl</div></div>
              <div className="box"><div className="l">Already Allocated</div><div className="v">{recommended.c.allocated} Qtl</div></div>
              <div className="box"><div className="l">Available</div><div className="v">{recommended.available} Qtl</div></div>
            </div>
            <div className="reco-stats" style={{ gridTemplateColumns: "1fr 1fr" }}>
              <div className="box"><div className="l">Available Slots</div><div className="v">{recommended.openSlots}</div></div>
              <div className="box"><div className="l">Crop</div><div className="v">✓ {f.crop}</div></div>
            </div>
            <div className="reason-box">Recommended because this centre is the nearest eligible centre with sufficient available capacity and an open slot.</div>
            <button className="btn btn-gold" onClick={() => setModal({ type: "allocConfirm", appId, code: recommended.c.code })}>Assign This Centre</button>
          </div>
        ) : (
          <div className="panel"><div className="empty-state">No centre currently meets crop, capacity and slot requirements for this farmer.<br />Consider manual review or check back once capacity frees up.</div></div>
        )}

        <div className="panel">
          <div className="panel-title">Alternative Centres</div>
          <table>
            <thead><tr><th>Centre</th><th>Distance</th><th>Capacity</th><th>Available</th><th>Crop</th><th></th></tr></thead>
            <tbody>
              {alternatives.map((s) => (
                <tr key={s.c.code}>
                  <td>{s.c.name}<div className="mono" style={{ fontSize: 10.5, color: "var(--ink-soft)" }}>{s.c.code}</div></td>
                  <td>{s.dist.toFixed(1)} km</td>
                  <td>{s.c.capacity} Qtl</td>
                  <td>{s.available} Qtl{!s.fits && <span style={{ color: "var(--red)", fontSize: 11 }}> (insufficient)</span>}</td>
                  <td>{s.cropOk ? "✓" : "✕"}</td>
                  <td style={{ whiteSpace: "nowrap" }}>
                    <button className="btn btn-outline btn-sm" onClick={() => setModal({ type: "centreDetail", code: s.c.code })}>View Details</button>{" "}
                    {s.eligible && <button className="btn btn-primary btn-sm" onClick={() => setModal({ type: "allocConfirm", appId, code: s.c.code })}>Assign</button>}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          <div style={{ fontSize: 11.5, color: "var(--ink-soft)", marginTop: 10 }}>
            A centre is only assignable when it accepts {f.crop}, is active, has ≥ {f.quantity.toFixed(2)} Qtl available, and has an open slot. Insufficient capacity: select another centre, or split the procurement across dates once that policy is enabled in Settings.
          </div>
        </div>
      </>
    );
  };

  /* ================= PAGE: UNASSIGNED ================= */
  const Unassigned = () => {
    const rows = farmers.filter((f) => f.status === "Verified");
    const withReco = rows.map((f) => {
      const scored = scoreCentres(f);
      const best = scored.find((s) => s.eligible) || scored[0];
      return { f, best };
    });
    return (
      <>
        <div className="page-head">
          <div><h2>Farmers Awaiting Centre Allocation</h2><div className="sub">{rows.length} Farmers Awaiting Allocation</div></div>
          <button className="btn btn-gold" onClick={autoAssignAll}>Auto Assign Centre</button>
        </div>
        <div className="panel" style={{ padding: 0 }}>
          <table>
            <thead><tr><th>Farmer</th><th>Village</th><th>Crop</th><th className="right">Eligible Qty</th><th>Nearest Centre</th><th>Distance</th><th>Available</th><th>Priority</th><th>Action</th></tr></thead>
            <tbody>
              {withReco.length ? withReco.map(({ f, best }) => (
                <tr key={f.appId}>
                  <td>{f.name}</td><td>{f.village}</td><td>{f.crop}</td>
                  <td className="right mono">{f.quantity.toFixed(2)} Qtl</td>
                  <td>{best ? best.c.name : "—"}</td>
                  <td>{best ? best.dist.toFixed(1) + " km" : "—"}</td>
                  <td>{best ? best.available + " Qtl" : "—"}</td>
                  <td>{f.quantity > 60 ? <span className="badge badge-pending">High</span> : <span className="badge badge-active">Normal</span>}</td>
                  <td><button className="btn btn-primary btn-sm" onClick={() => go("allocate", f.appId)}>Review &amp; Assign</button></td>
                </tr>
              )) : <tr><td colSpan={9}><div className="empty-state">No farmers currently awaiting centre allocation.</div></td></tr>}
            </tbody>
          </table>
        </div>
      </>
    );
  };

  /* ================= PAGE: SLOT & TOKEN ================= */
  const SlotPage = ({ appId }) => {
    const f = findFarmer(appId);
    if (!f) return <div className="empty-state">Farmer not found.</div>;
    if (!f.centre) {
      return (
        <div className="empty-state">
          This farmer has not been allocated a centre yet.<br />
          <button className="btn btn-primary" style={{ marginTop: 14 }} onClick={() => go("allocate", appId)}>Go to Centre Allocation</button>
        </div>
      );
    }
    const c = findCentre(f.centre);
    return (
      <>
        <div className="page-head">
          <div><h2>Slot &amp; Token</h2><div className="sub">Application ID: <span className="mono">{f.appId}</span> · Centre: {c.name}</div></div>
          <button className="btn btn-outline btn-sm" onClick={() => go("applications")}>← Back to applications</button>
        </div>
        <div className="panel"><WorkflowStepper farmer={f} /></div>

        <div className="grid-2">
          <div className="panel">
            <div className="panel-title">Available Slots — {c.name}</div>
            <table>
              <thead><tr><th>Time</th><th>Status</th><th></th></tr></thead>
              <tbody>
                {c.slots.map(([t, cap, booked], i) => {
                  const full = booked >= cap;
                  const label = full ? "Full" : booked > 0 ? booked + "/" + cap + " booked" : "Available";
                  const chosen = f.slot === t;
                  return (
                    <tr key={i}>
                      <td>{t}</td>
                      <td>{chosen ? <span className="badge badge-verified">Selected</span> : full ? <span className="badge badge-rejected">{label}</span> : <span className="badge badge-active">{label}</span>}</td>
                      <td>{!full && f.status !== "Token Generated" && <button className="btn btn-outline btn-sm" onClick={() => selectSlot(appId, t)}>Select</button>}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>

          <div className="panel">
            {f.status === "Token Generated" ? (
              <>
                <div className="panel-title">Token Generated</div>
                <div className="token-card">
                  <div className="tlabel">PROCUREMENT TOKEN</div>
                  <div className="tnum">{f.tokenNo}</div>
                  <div className="kv" style={{ textAlign: "left" }}>
                    <div className="kv-row"><span>Farmer</span><span>{f.name}</span></div>
                    <div className="kv-row"><span>Centre</span><span>{c.name}</span></div>
                    <div className="kv-row"><span>Date</span><span>{f.slotDate}</span></div>
                    <div className="kv-row"><span>Time</span><span>{f.slot}</span></div>
                    <div className="kv-row"><span>Quantity</span><span>{f.allocatedQty.toFixed(2)} Qtl</span></div>
                  </div>
                </div>
              </>
            ) : (
              <>
                <div className="panel-title">Assign Slot &amp; Generate Token</div>
                <div className="form-row"><label>Date</label><input type="date" value={slotDraftDate} onChange={(e) => setSlotDraftDate(e.target.value)} /></div>
                <div className="form-row"><label>Time</label><input type="text" value={f.slot || ""} placeholder="Select a slot on the left" readOnly /></div>
                <div className="form-row"><label>Quantity</label><input type="text" value={f.allocatedQty.toFixed(2) + " Qtl"} readOnly /></div>
                <button className="btn btn-gold" disabled={!f.slot} onClick={() => generateToken(appId)}>Generate Token</button>
              </>
            )}
          </div>
        </div>

        <div className="panel">
          <div className="panel-title">Farmer Status Timeline</div>
          <StatusTimeline f={f} />
        </div>
      </>
    );
  };

  /* ================= PAGE: CENTRES ================= */
  const Centres = () => (
    <>
      <div className="page-head"><div><h2>Procurement Centres</h2><div className="sub">{centres.length} centres registered under Gonda district cluster</div></div></div>
      {centres.map((c) => {
        const pct = Math.round((c.allocated / c.capacity) * 100);
        const barClass = pct >= 90 ? "red" : pct > 70 ? "amber" : "green";
        const remaining = c.capacity - c.allocated;
        const openSlots = c.slots.filter((s) => s[2] < s[1]).length;
        return (
          <div className="panel" key={c.code}>
            <div className="panel-title">
              {c.name} <span className={`badge ${c.status === "ACTIVE" ? "badge-active" : "badge-closed"}`}>{c.status === "ACTIVE" ? "🟢 ACTIVE" : "⚫ CLOSED"}</span>
            </div>
            <div className="grid-2">
              <div className="kv">
                <div className="kv-row"><span>Centre Code</span><span className="mono">{c.code}</span></div>
                <div className="kv-row"><span>District / Tehsil</span><span>{c.district} / {c.tehsil}</span></div>
                <div className="kv-row"><span>Location</span><span>{c.location}</span></div>
                <div className="kv-row"><span>Accepted Crops</span><span>{c.crops.join(", ")}</span></div>
                <div className="kv-row"><span>Number of Farmers</span><span>{c.farmers}</span></div>
                <div className="kv-row"><span>Available Slots</span><span>{openSlots}</span></div>
              </div>
              <div>
                <div className="cap-box" style={{ border: "none", padding: 0 }}>
                  <div className="lbl">Daily Capacity</div>
                  <div className="num">{c.allocated} / {c.capacity} Qtl</div>
                  <div className="bar-track"><div className={`bar-fill ${barClass}`} style={{ width: Math.min(pct, 100) + "%" }} /></div>
                  <div style={{ fontSize: 11.5, color: "var(--ink-soft)", marginTop: 6 }}>{pct}% Utilized · {remaining} Qtl Remaining</div>
                </div>
              </div>
            </div>
            <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginTop: 14 }}>
              <button className="btn btn-outline btn-sm" onClick={() => setModal({ type: "editCapacity", code: c.code, value: c.capacity })}>Edit Capacity</button>
              <button className="btn btn-outline btn-sm" onClick={() => setModal({ type: "addSlot", code: c.code, time: "", cap: 10 })}>Add Slot</button>
              <button className="btn btn-outline btn-sm" onClick={() => toggleCentre(c.code)}>{c.status === "ACTIVE" ? "Close Centre" : "Reopen Centre"}</button>
              <button className="btn btn-outline btn-sm" onClick={() => setModal({ type: "centreFarmers", code: c.code })}>View Farmers</button>
              <button className="btn btn-outline btn-sm" onClick={() => go("procurement")}>View Procurement</button>
              <button className="btn btn-outline btn-sm" onClick={() => toast("Map view is not available in this prototype.")}>View Map</button>
            </div>
          </div>
        );
      })}
    </>
  );

  /* ================= PAGE: TOKENS / SLOTS / PROCUREMENT / PAYMENTS ================= */
  const Tokens = () => {
    const rows = farmers.filter((f) => f.tokenNo);
    return (
      <>
        <div className="page-head"><div><h2>Token Management</h2><div className="sub">{rows.length} tokens generated</div></div></div>
        <div className="panel" style={{ padding: 0 }}>
          <table>
            <thead><tr><th>Token No.</th><th>Farmer</th><th>Centre</th><th>Date</th><th>Time</th><th className="right">Quantity</th><th>Status</th></tr></thead>
            <tbody>
              {rows.length ? rows.map((f) => (
                <tr key={f.appId}>
                  <td className="mono">{f.tokenNo}</td><td>{f.name}</td><td>{findCentre(f.centre).name}</td>
                  <td>{f.slotDate}</td><td>{f.slot}</td><td className="right mono">{f.allocatedQty.toFixed(2)} Qtl</td>
                  <td><span className="badge badge-allocated">Issued</span></td>
                </tr>
              )) : <tr><td colSpan={7}><div className="empty-state">No tokens generated yet.</div></td></tr>}
            </tbody>
          </table>
        </div>
      </>
    );
  };

  const SlotsMgmt = () => (
    <>
      <div className="page-head"><div><h2>Slot Management</h2><div className="sub">Slot occupancy across all active centres</div></div></div>
      {centres.filter((c) => c.status === "ACTIVE").map((c) => (
        <div className="panel" key={c.code}>
          <div className="panel-title">{c.name} <span className="mono" style={{ fontSize: 11, color: "var(--ink-soft)" }}>{c.code}</span></div>
          <table>
            <thead><tr><th>Time</th><th>Booked</th><th>Capacity</th><th>Status</th></tr></thead>
            <tbody>
              {c.slots.map(([t, cap, booked], i) => (
                <tr key={i}>
                  <td>{t}</td><td>{booked}</td><td>{cap}</td>
                  <td>{booked >= cap ? <span className="badge badge-rejected">Full</span> : booked > 0 ? <span className="badge badge-pending">Filling</span> : <span className="badge badge-active">Available</span>}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      ))}
    </>
  );

  const Procurement = () => {
    const rows = farmers.filter((f) => f.status === "Token Generated");
    return (
      <>
        <div className="page-head"><div><h2>Procurement</h2><div className="sub">Farmers with an issued token, pending arrival at centre</div></div></div>
        <div className="panel" style={{ padding: 0 }}>
          <table>
            <thead><tr><th>Token</th><th>Farmer</th><th>Centre</th><th className="right">Quantity</th><th>Status</th></tr></thead>
            <tbody>
              {rows.length ? rows.map((f) => (
                <tr key={f.appId}>
                  <td className="mono">{f.tokenNo}</td><td>{f.name}</td><td>{findCentre(f.centre).name}</td>
                  <td className="right mono">{f.allocatedQty.toFixed(2)} Qtl</td>
                  <td><span className="badge badge-pending">Awaiting Arrival</span></td>
                </tr>
              )) : <tr><td colSpan={5}><div className="empty-state">No procurement scheduled yet — generate tokens from Slot &amp; Token pages.</div></td></tr>}
            </tbody>
          </table>
        </div>
      </>
    );
  };

  const Payments = () => (
    <>
      <div className="page-head"><div><h2>Payments</h2><div className="sub">Payments are released after procurement completion</div></div></div>
      <div className="panel"><div className="empty-state">No completed procurements yet in this demo session, so no payments are due.<br />Once a farmer's status reaches "Procurement Completed", their payment will appear here.</div></div>
    </>
  );

  const Reports = () => (
    <>
      <div className="page-head"><div><h2>Reports &amp; Audit Log</h2><div className="sub">Every verification, allocation and token action is recorded for transparency</div></div></div>
      <div className="panel">
        {auditLog.length ? auditLog.map((a, i) => (
          <div className="audit-item" key={i}>
            <div className="time">{a.time}<br /><span className="mono">{a.admin}</span></div>
            <div className="body"><b>{a.action}</b><br /><span style={{ color: "var(--ink-soft)" }}>{a.detail}</span></div>
          </div>
        )) : <div className="empty-state">No actions recorded yet.</div>}
      </div>
    </>
  );

  const Complaints = () => (
    <>
      <div className="page-head"><div><h2>Complaints</h2><div className="sub">{COMPLAINTS.length} complaints on record (mock data)</div></div></div>
      <div className="panel" style={{ padding: 0 }}>
        <table>
          <thead><tr><th>Complaint ID</th><th>Farmer</th><th>Subject</th><th>Status</th></tr></thead>
          <tbody>
            {COMPLAINTS.map((c) => (
              <tr key={c.id}>
                <td className="mono">{c.id}</td><td>{c.farmer}</td><td>{c.subject}</td>
                <td><span className={`badge ${c.status === "Resolved" ? "badge-verified" : c.status === "Open" ? "badge-pending" : "badge-review"}`}>{c.status}</span></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </>
  );

  const SettingsPage = () => {
    const [draft, setDraftState] = useState(config.yieldPerHectare);
    return (
      <>
        <div className="page-head"><div><h2>Settings</h2><div className="sub">Configure the eligibility formula and allocation policy used across the portal</div></div></div>
        <div className="panel">
          <div className="panel-title">Eligibility Formula <span className="tag">Admin configurable</span></div>
          <div style={{ fontSize: 12.5, color: "var(--ink-soft)", marginBottom: 14 }}>
            Eligible quantity = declared crop area (hectares) × yield per hectare (Qtl), by crop. No procurement formula is hard-coded — values below drive every eligibility calculation in the system.
          </div>
          <div className="two-col">
            {Object.keys(draft).map((crop) => (
              <div className="form-row" key={crop}>
                <label>{crop} — yield per hectare (Qtl)</label>
                <input type="number" step="0.05" value={draft[crop]} onChange={(e) => setDraftState((d) => ({ ...d, [crop]: parseFloat(e.target.value) || 0 }))} />
              </div>
            ))}
          </div>
          <button className="btn btn-primary" onClick={() => saveYields(draft)}>Save Formula</button>
        </div>
        <div className="panel">
          <div className="panel-title">Allocation Policy</div>
          <label style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 13 }}>
            <input type="checkbox" checked={config.autoSplitAllocation} onChange={(e) => toggleAutoSplit(e.target.checked)} />
            Automatically split a farmer's procurement across dates when a single centre lacks sufficient capacity
          </label>
          <div style={{ fontSize: 11.5, color: "var(--ink-soft)", marginTop: 8 }}>Disabled by default — when off, the system asks the admin to pick another centre instead of auto-splitting.</div>
        </div>
      </>
    );
  };

  /* ================= ROUTER ================= */
  const renderView = () => {
    switch (view) {
      case "dashboard": return <Dashboard />;
      case "applications": return <Applications title="Farmer Applications" />;
      case "verification-list": return <Applications title="Farmer Verification" />;
      case "eligible": return <Eligible />;
      case "centres": return <Centres />;
      case "tokens": return <Tokens />;
      case "procurement": return <Procurement />;
      case "payments": return <Payments />;
      case "reports": return <Reports />;
      case "complaints": return <Complaints />;
      case "settings": return <SettingsPage />;
      case "verify": return <Verify appId={activeFarmerId} />;
      case "allocate": return <Allocate appId={activeFarmerId} />;
      case "slot": return <SlotPage appId={activeFarmerId} />;
      default: return <div className="empty-state">Page not found.</div>;
    }
  };

  /* ================= MODAL ================= */
  const renderModal = () => {
    if (!modal) return null;
    if (modal.type === "reject") {
      const reasons = ["Land record mismatch", "Duplicate farmer", "Invalid information", "Crop information mismatch", "Documents/data could not be verified"];
      return (
        <div className="modal-bg" onClick={closeModal}>
          <div className="modal" onClick={(e) => e.stopPropagation()}>
            <h3>Reject Application</h3>
            <div className="form-row">
              <label>Rejection Reason</label>
              <select value={modal.reason} onChange={(e) => setModal((m) => ({ ...m, reason: e.target.value }))}>
                {reasons.map((r) => <option key={r}>{r}</option>)}
              </select>
            </div>
            <div className="modal-actions">
              <button className="btn btn-outline" onClick={closeModal}>Cancel</button>
              <button className="btn btn-danger" onClick={() => confirmReject(modal.appId, modal.reason)}>Reject Application</button>
            </div>
          </div>
        </div>
      );
    }
    if (modal.type === "centreDetail") {
      const c = findCentre(modal.code);
      const pct = Math.round((c.allocated / c.capacity) * 100);
      const barClass = pct > 90 ? "red" : pct > 70 ? "amber" : "green";
      return (
        <div className="modal-bg" onClick={closeModal}>
          <div className="modal" onClick={(e) => e.stopPropagation()}>
            <h3>{c.name}</h3>
            <div className="kv">
              <div className="kv-row"><span>Centre Code</span><span className="mono">{c.code}</span></div>
              <div className="kv-row"><span>District / Tehsil</span><span>{c.district} / {c.tehsil}</span></div>
              <div className="kv-row"><span>Location</span><span>{c.location}</span></div>
              <div className="kv-row"><span>Accepted Crops</span><span>{c.crops.join(", ")}</span></div>
              <div className="kv-row"><span>Daily Capacity</span><span>{c.capacity} Qtl</span></div>
              <div className="kv-row"><span>Allocated</span><span>{c.allocated} Qtl</span></div>
              <div className="kv-row"><span>Status</span><span>{c.status}</span></div>
            </div>
            <div className="bar-track"><div className={`bar-fill ${barClass}`} style={{ width: pct + "%" }} /></div>
            <div className="modal-actions"><button className="btn btn-outline btn-block" onClick={closeModal}>Close</button></div>
          </div>
        </div>
      );
    }
    if (modal.type === "allocConfirm") {
      const f = findFarmer(modal.appId);
      const c = findCentre(modal.code);
      const dist = (DISTANCES[f.village] || {})[c.code] ?? 99;
      const available = c.capacity - c.allocated;
      if (f.quantity > available) {
        return (
          <div className="modal-bg" onClick={closeModal}>
            <div className="modal" onClick={(e) => e.stopPropagation()}>
              <h3>Insufficient Capacity</h3>
              <p style={{ fontSize: 13.5 }}>Insufficient centre capacity. Select another centre or split the procurement across available dates according to configured policy.</p>
              <div className="modal-actions"><button className="btn btn-outline btn-block" onClick={closeModal}>Close</button></div>
            </div>
          </div>
        );
      }
      return (
        <div className="modal-bg" onClick={closeModal}>
          <div className="modal" onClick={(e) => e.stopPropagation()}>
            <h3>Confirm Centre Allocation</h3>
            <div className="kv">
              <div className="kv-row"><span>Farmer</span><span>{f.name}</span></div>
              <div className="kv-row"><span>Eligible Quantity</span><span>{f.quantity.toFixed(2)} Qtl</span></div>
              <div className="kv-row"><span>Recommended Centre</span><span>{c.name}</span></div>
              <div className="kv-row"><span>Distance</span><span>{dist.toFixed(1)} km</span></div>
              <div className="kv-row"><span>Available Capacity</span><span>{available} Qtl</span></div>
              <div className="kv-row"><span>Proposed Allocation</span><span>{f.quantity.toFixed(2)} Qtl</span></div>
            </div>
            <div className="modal-actions">
              <button className="btn btn-outline" onClick={closeModal}>Cancel</button>
              <button className="btn btn-gold" onClick={() => confirmAllocation(modal.appId, modal.code)}>Confirm Allocation</button>
            </div>
          </div>
        </div>
      );
    }
    if (modal.type === "autoAssign") {
      return (
        <div className="modal-bg" onClick={closeModal}>
          <div className="modal" onClick={(e) => e.stopPropagation()}>
            <h3>Proposed Auto-Assignments</h3>
            <div style={{ maxHeight: 320, overflow: "auto" }}>
              <table style={{ fontSize: 12.5 }}>
                <thead><tr><th>Farmer</th><th>Centre</th><th>Qty</th></tr></thead>
                <tbody>
                  {pendingAuto.map((p) => (
                    <tr key={p.f.appId}><td>{p.f.name}</td><td>{p.best ? p.best.c.name : "No eligible centre"}</td><td>{p.f.quantity.toFixed(2)} Qtl</td></tr>
                  ))}
                </tbody>
              </table>
            </div>
            <div style={{ fontSize: 11.5, color: "var(--ink-soft)", margin: "12px 0" }}>
              Review the proposed assignments above. Confirming will reserve capacity, generate allocation IDs and record an audit entry for each farmer.
            </div>
            <div className="modal-actions">
              <button className="btn btn-outline" onClick={closeModal}>Cancel</button>
              <button className="btn btn-gold" onClick={confirmAutoAssign}>Confirm All Assignments</button>
            </div>
          </div>
        </div>
      );
    }
    if (modal.type === "editCapacity") {
      return (
        <div className="modal-bg" onClick={closeModal}>
          <div className="modal" onClick={(e) => e.stopPropagation()}>
            <h3>Edit Capacity — {findCentre(modal.code).name}</h3>
            <div className="form-row">
              <label>Daily Capacity (Qtl)</label>
              <input type="number" value={modal.value} onChange={(e) => setModal((m) => ({ ...m, value: parseFloat(e.target.value) || 0 }))} />
            </div>
            <div className="modal-actions">
              <button className="btn btn-outline" onClick={closeModal}>Cancel</button>
              <button className="btn btn-primary" onClick={() => saveCapacity(modal.code, modal.value)}>Save Changes</button>
            </div>
          </div>
        </div>
      );
    }
    if (modal.type === "addSlot") {
      return (
        <div className="modal-bg" onClick={closeModal}>
          <div className="modal" onClick={(e) => e.stopPropagation()}>
            <h3>Add Slot</h3>
            <div className="form-row">
              <label>Time Range</label>
              <input type="text" placeholder="e.g. 03:00–04:00" value={modal.time} onChange={(e) => setModal((m) => ({ ...m, time: e.target.value }))} />
            </div>
            <div className="form-row">
              <label>Slot Capacity (farmers)</label>
              <input type="number" value={modal.cap} onChange={(e) => setModal((m) => ({ ...m, cap: parseInt(e.target.value) || 10 }))} />
            </div>
            <div className="modal-actions">
              <button className="btn btn-outline" onClick={closeModal}>Cancel</button>
              <button className="btn btn-primary" onClick={() => saveSlot(modal.code, modal.time, modal.cap)}>Add Slot</button>
            </div>
          </div>
        </div>
      );
    }
    if (modal.type === "centreFarmers") {
      const rows = farmers.filter((f) => f.centre === modal.code);
      return (
        <div className="modal-bg" onClick={closeModal}>
          <div className="modal" onClick={(e) => e.stopPropagation()}>
            <h3>Farmers — {modal.code}</h3>
            <div style={{ maxHeight: 320, overflow: "auto" }}>
              <table style={{ fontSize: 12.5 }}>
                <thead><tr><th>Farmer</th><th>Qty</th><th>Status</th></tr></thead>
                <tbody>
                  {rows.length ? rows.map((f) => (
                    <tr key={f.appId}><td>{f.name}</td><td>{f.allocatedQty.toFixed(2)} Qtl</td><td>{f.status}</td></tr>
                  )) : <tr><td colSpan={3}>No farmers assigned yet.</td></tr>}
                </tbody>
              </table>
            </div>
            <div className="modal-actions"><button className="btn btn-outline btn-block" onClick={closeModal}>Close</button></div>
          </div>
        </div>
      );
    }
    return null;
  };

  /* ================= SHELL ================= */
  return (
    <div className="annsetu-root">
      <style>{CSS}</style>
      <div id="shell">
        <div className="sidebar">
          <div className="sidebar-brand">
            <Seal small />
            <div><h1><span className="brand-ann">Ann</span><span className="brand-disha">Disha</span></h1><span>Admin Portal</span></div>
          </div>
          <ul className="nav">
            {NAV_ITEMS.map((n) => (
              <li key={n.id}>
                <button className={view === n.id ? "active" : ""} onClick={() => go(n.id)}>
                  <span className="icon">{n.icon}</span><span className="lbl-txt">{n.label}</span>
                </button>
              </li>
            ))}
          </ul>
          <div className="sidebar-foot">Prototype build — mock data only.<br />Not connected to any live government system.</div>
        </div>
        <div className="main">
          <div className="topbar">
            <div className="crumb">{crumbFor()}</div>
            <div className="who">
              <span className="badge-id">{new Date().toLocaleDateString("en-IN", { day: "2-digit", month: "short", year: "numeric" })}</span>
              <span><strong>Anil Verma</strong> · Admin</span>
              <span className="badge-id">ADM-001</span>
              <button className="logout-link" onClick={() => setLoggedIn(false)}>Sign out</button>
            </div>
          </div>
          <div className="content">{renderView()}</div>
          <div className="footer-strip">AnnDisha Prototype — Demo system. Not an official Government of Uttar Pradesh portal.</div>
        </div>
      </div>

      {renderModal()}

      <div className="toast-wrap">
        {toasts.map((t) => <div className="toast" key={t.id}>{t.msg}</div>)}
      </div>
    </div>
  );
}
